Ext.define("bcp.view.FileAttachmentGridViewController", {
    extend: "Ext.app.ViewController",
    alias: "controller.fileattachmentgrid",

    onUploadFile: function (button, e, eOpts) {
        var model = this.getViewModel(),
            store = Ext.getStore("RequestFiles"),
            req = model.get("generalInfo");
        if (req) {
            var formWindow = Ext.create("Ext.window.Window", {
                    modal: true,
                    height: 320,
                    width: 480,
                    closable: false,
                    title: "Upload File",
                    layout: {type: "vbox", align: "stretch"}
                }),
                form = Ext.create("widget.fileuploadform"),
                newRecord = Ext.create("model.bcpfile", {
                    requestId: req.get("requestId")
                });

            //set record
            form.lookupController().getViewModel().set("record", newRecord);

            //load record
            form.getForm().loadRecord(newRecord);
            //set event listeners
            form.on({
                cancelUpload: {
                    fn: function (win, data) {
                        formWindow.destroy();
                    },
                    scope: this,
                    single: true
                }
            });
            form.on({
                uploaded: {
                    fn: function (win, data) {
                        formWindow.destroy();
                        store.reload();
                    },
                    scope: this,
                    single: true
                }
            });
            //add form to window
            formWindow.add(form);
            //add window to view
            this.view.add(formWindow);
            //show window
            formWindow.show();
        } else {
            Ext.Msg.alert("Warning", "Please select a request record from the list first.");
        }
    },

    onDownloadFile: function (button, e, eOpts) {
        var record = this.getViewModel().get("fileRecord"),
            fileId = record.get("fileId");
        //issue 610
        if (fileId == -999) {
            var pdfUrl = "resources/files/IT_Buying_Service_IT_Compliance_in_Acquisition_Checklist_v5.0-NIST.pdf";
            // Create a new window to display the PDF
            Ext.Ajax.request({
                url: pdfUrl,
                method: "HEAD", // HEAD request only checks headers
                success: function (response) {
                    if (response.status === 200) {
                        // File exists
                        window.open(
                            pdfUrl,
                            "_blank",
                            "PrefilledITChecklist",
                            "width=600,height=520,resizable=yes,scrollbars=yes"
                        );
                    } else {
                        bcp.util.CommonUtil.showError("prefilled IT Checklist PDF file not found.");
                    }
                },
                failure: function (response) {
                    bcp.util.CommonUtil.showError(`Error accessing PDF file for ID: ${fileId}: ${response.statusText}`);
                }
            });
        } else {
            bcp.util.DownloadFile.download({
                method: "GET",
                url: "/empbc/v1/attachments/" + fileId
            });
        }
    },

    onDownloadFileAllPdf: function (button, e, eOpts) {
        let model = this.getViewModel(),
            store = Ext.getStore("RequestFiles"),
            req = model.get("generalInfo"),
            reqId = -1;

        if (store.getCount() === 0) {
            Ext.Msg.alert("Info", "There are no files to download.");
            return;
        }

        if (req) {
            reqId = req.get("requestId");
        }

        //remember to handle prefilled IT Checklist
        if (reqId) {
            bcp.util.DownloadFile.download({
                method: "GET",
                url: "/empbc/v1/attachments/all_to_pdf/" + reqId
            });
        } else {
            Ext.Msg.alert("Error", "Error retreiving the request id.");
        }
    },

    onDownloadFileSelectedZip: function (button, e, eOpts) {
        var grid = this.getView(); // Get the grid panel
        var selectedRecords = grid.getSelectionModel().getSelection();

        if (selectedRecords.length === 0) {
            Ext.Msg.alert("Info", "Please select at least one file to download.");
            return;
        }

        var fileIds = selectedRecords.map(function(record) {
            return record.get("fileId");
        }).filter(function(id) {
            // Filter out special non-downloadable IDs, e.g., the prefilled IT checklist
            return id !== -999;
        });

        if (fileIds.length === 0) {
            Ext.Msg.alert(
                "Info",
                "No downloadable files selected. The prefilled IT Checklist, if selected, cannot be included in the zip."
            );
            return;
        }

        // Join file IDs into a comma-separated string
        var idsString = fileIds.join(',');
        // Base64 encode the string of IDs
        // Note: btoa might have issues with non-ASCII characters, but for numeric IDs and commas, it's fine.
        var base64EncodedIds = btoa(idsString);
        // URL-encode the Base64 string to make it safe for a URL path segment
        var fullyEncodedIds = encodeURIComponent(base64EncodedIds);

        var downloadUrl = "/empbc/v1/attachments/selected_to_zip/" + fullyEncodedIds;

        bcp.util.DownloadFile.download({
            method: "GET",
            url: downloadUrl
        });
    },

    remove: function (button, e, eOpts) {
        let model = this.getViewModel(),
            record = model.get("fileRecord"),
            fileId = record.get("fileId"),
            fileCategory = record.get("categoryId"),
            store = Ext.getStore("RequestFiles"),
            url = "";

        if (fileCategory === 5) {
            Ext.Msg.alert(
                "Warning",
                "The Shopping Cart File, which is linked with the Shopping Cart Item, cannot be removed from here. Please remove it from the Items grid"
            );
            return;
        }

        // Ask user to confirm this action
        Ext.Msg.confirm("Confirm Delete", "Are you sure you want to delete this file attachment?", function (result) {
            // User confirmed yes
            if (result == "yes") {
                url = bcp.config.Runtime.getServerBaseUrl() + "attachments/" + fileId;
                var method = "DELETE";
                Ext.Ajax.request({
                    url: url,
                    method: method,
                    scope: this,
                    success: function (response) {
                        // reload store
                        store.reload();
                    }
                });
            }
        });
    },

    // The selectFile listener is replaced by onGridSelectionChange
    /* selectFile: function (rowmodel, record, index, eOpts) {
        var refs = this.getReferences();
        // Set selected record
        this.getViewModel().set("fileRecord", record);
        //show buttons
        refs.btnDownload.show();
        refs.btnRemove.show();
    },*/

    onGridSelectionChange: function (selModel, selectedRecords, eOpts) {
        var refs = this.getReferences();
        var viewModel = this.getViewModel();
        var numSelected = selectedRecords.length;
        var btnDownload = refs.btnDownload;
        var btnRemove = refs.btnRemove;

        if (numSelected === 1) {
            viewModel.set("fileRecord", selectedRecords[0]);
            btnDownload.show();
            btnDownload.enable();
            btnRemove.show();
            btnRemove.enable();
        } else if (numSelected > 1) {
            viewModel.set("fileRecord", null); // Clear record if multiple are selected
            btnDownload.show(); // Keep buttons visible
            btnDownload.disable(); // Disable if more than one selected
            btnRemove.show();   // Keep buttons visible
            btnRemove.disable();  // Disable if more than one selected
        } else { // numSelected === 0
            viewModel.set("fileRecord", null);
            btnDownload.hide();
            btnRemove.hide();
        }
    },

    onViewAdded: function (component, container, pos, eOpts) {
        var refs = this.getReferences(),
            store = Ext.getStore("RequestFiles");

        //clean data from store first; found a case when going from a request(with attached file) detail page to audit report 
        //view, the attached files for that request was showing in the grid
        //before doing any search in the audit report
        store.removeAll();

        //set button visibility
        //BAO and BCH can upload or remove files at any time
        if (bcp.util.CommonUtil.isUserInRole(["Director", "Bankcard Approving Official", "Bankcard Holder"])) {
            refs.btnUpload.enable();
            refs.btnRemove.enable();
        } else {
            if (container.xtype == "readonlyrequest" || component.readOnly) {
                //if readonly mode
                refs.btnUpload.disable();
                refs.btnRemove.disable();
            } else {
                refs.btnUpload.enable();
                refs.btnRemove.enable();
            }
        }
    }
});
